'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const qs={flood:['Does the policy cover rainwater ingress, surface flooding and sewer backup separately?','Are there waiting periods, excesses, sublimits or proof requirements?','Does it cover temporary accommodation or business interruption?'],storm:['How does the policy define windstorm and the minimum event threshold?','What are the exclusions for roof, window or maintenance-related damage?','What evidence and claim deadlines would apply after a storm?'],heat:['Is heat-related equipment failure, spoilage or interruption covered at all?','Does the insurer require a named insured physical damage trigger?','Would any parametric product pay based on an index, and which exact trigger and exclusions apply?']};
$('insurance-form').addEventListener('submit',e=>{e.preventDefault();let risk=$('insurance-risk').value,profile=$('insurance-profile').value;let prefix=profile==='renter'?'Ask separately about contents versus landlord building coverage.':profile==='owner'?'Ask about building versus personal contents limits.':'Ask about covered physical damage and any business-interruption conditions.';$('insurance-results').innerHTML=[prefix,...qs[risk]].map(x=>'<li>'+esc(x)+'</li>').join('')});
